add_filter( 'woocommerce_checkout_fields', 'perfectpixel_virtual_cart_minimal_fields', 9999 );
add_filter( 'woocommerce_enable_order_notes_field', 'perfectpixel_virtual_cart_hide_notes', 9999 );

function perfectpixel_cart_is_virtual_only() {
	if ( ! function_exists( 'WC' ) || ! WC()->cart || WC()->cart->is_empty() ) {
		return false;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( empty( $item['data'] ) || ! $item['data']->is_virtual() ) {
			return false;
		}
	}
	return true;
}

function perfectpixel_virtual_cart_minimal_fields( $fields ) {
	if ( ! perfectpixel_cart_is_virtual_only() ) {
		return $fields;
	}
	$keep              = array( 'billing_first_name', 'billing_last_name', 'billing_email' );
	$fields['billing'] = array_intersect_key( $fields['billing'], array_flip( $keep ) );
	return $fields;
}

function perfectpixel_virtual_cart_hide_notes( $enabled ) {
	return perfectpixel_cart_is_virtual_only() ? false : $enabled;
}
